const save = async () => {
  if (!canSave || !editingRef.current || savingRef.current) return
  savingRef.current = true
  setSaving(true)
  const saved = await onEdit(trimmed)
  if (!alive.current) return
  savingRef.current = false
  setSaving(false)
  if (saved) {
    editingRef.current = false
    setShown(trimmed)
    setEditing(false)
  }
}

const onEdit = async (body: string) => {
  const { context: ctx, worktree: tree } = live.current
  try {
    await ctx.call('quirky.git/editNote', { worktree: tree, id: note.id, body })
    return true
  } catch (error) {
    return toastNoteFailure(ctx, 'Failed to save comment', error)
  }
}

const onSend = async (scope: SendableScope, to: SendTarget) => {
  const sending = context.call('quirky.git/sendNotes', { worktree, ...scope.params, ...to })
  hold(scope.unsent.map((note) => note.id), sending)
  context.toast('Sending notes...', '')
  try {
    await sending
    context.toast('Notes sent.', '')
  } catch (error) {
    context.toast('Failed to send notes', messageOf(error), { kind: 'error' })
  }
}

