const show = async () => {
  const box = anchor.current?.getBoundingClientRect()
  try {
    const targets = (await context.call('quirky.git/noteTargets', { worktree })) as Targets
    if (alive.current) setMenu({ x: box?.left ?? 0, y: box?.bottom ?? 0, targets })
  } catch (error) {
    context.toast('Failed to load agents', messageOf(error), { kind: 'error' })
  }
}

const onSaveBase = async (params: { base: string } | { clear: true }) => {
  setSaving(true)
  setSaveError(null)
  try {
    await context.call('quirky.git/setBase', { worktree, ...params })
    await onChanged()
    if (!alive.current) return
    setSaving(false)
    onDialogClose()
  } catch (e) {
    if (!alive.current) return
    setSaveError(messageOf(e))
    setSaving(false)
  }
}

